set -u
R=/scratch/jjyeung/orch_n30
date -u +%TZ
tmux kill-session -t sb_rowD4 2>/dev/null; sleep 3; echo "D4 left: $(pgrep -af "label sb_rowD4" | wc -l)"
mkdir -p $R/sb_rowD5/prompts $R/sb_rowD5/out
echo  | base64 -d > $R/sb_rowD5/prompts/sb_rowD5.md
{ echo sb_rowD5; cat $R/sb_queue/queue.txt; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt
mkdir -p $R/sb_arev2; cp $R/sb_cursor_probe/AGENTS.md $R/sb_arev2/AGENTS.md
echo  | base64 -d > $R/sb_arev2/PROMPT.md
cd $R/sb_arev2 && tmux new-session -d -s sb_arev2 "timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
mkdir -p $R/sb_brev3; cp $R/sb_cursor_probe/AGENTS.md $R/sb_brev3/AGENTS.md
echo  | base64 -d > $R/sb_brev3/PROMPT.md
cd $R/sb_brev3 && tmux new-session -d -s sb_brev3 "timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
mkdir -p $R/sb_afrev; cp $R/sb_cursor_probe/AGENTS.md $R/sb_afrev/AGENTS.md
echo  | base64 -d > $R/sb_afrev/PROMPT.md
cd $R/sb_afrev && tmux new-session -d -s sb_afrev "timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 20; tmux ls | cut -d: -f1 | tr "\n" " "; echo
cat $R/sb_queue/queue.txt | tr "\n" " "; echo; tail -2 $R/sb_queue/codexq.log
grep -n "pgrep\|RUNNING\|avail" $R/sb_queue/codexq2.sh | head -12
echo == f64; tail -c 600 $R/sb_f64/cursor.log; head -c 600 $R/sb_f64/STATUS.md; echo; echo == recrev; tail -c 400 $R/sb_recrev/cursor.log; ls $R/sb_recrev $R/sb_recrev/notes | tr "\n" " "
echo == A2; head -60 $R/sb_rowA/out/REPORT.md; ls $R/sb_rowA/out | tr "\n" " "
echo == B3; head -70 $R/sb_rowB3/out/REPORT.md
